const insights = $input.item.json;
const insightsRaw = insights?.data || [];
const post = $('Definir Métricas').item.json;

const get = (name) => {
  const found = insightsRaw.find(i => i.name === name);
  return found?.values?.[0]?.value ?? 0;
};

// Extração das URLs de imagem por tipo de mídia
const thumbnailUrl = post.thumbnail_url || null;
const mediaUrl = post.media_url || null;
let coverCandidate = null;

if (post.media_type === 'IMAGE') {
  coverCandidate = mediaUrl;
} else if (post.media_type === 'VIDEO') {
  // Reels: thumbnail_url é mais estável que media_url para vídeos
  coverCandidate = thumbnailUrl || mediaUrl;
} else if (post.media_type === 'CAROUSEL_ALBUM') {
  // Usar o primeiro filho do carrossel — tem a capa real
  const firstChild = post.children?.data?.[0];
  if (firstChild) {
    coverCandidate = firstChild.media_type === 'VIDEO'
      ? (firstChild.thumbnail_url || firstChild.media_url || null)
      : (firstChild.media_url || null);
  }
  // Fallback para a capa do próprio álbum (nem sempre disponível)
  if (!coverCandidate) coverCandidate = mediaUrl;
}

return {
  json: {
    post_id: post.id,
    account_id: post.account_id,
    username: post.username,
    posted_at: post.timestamp,
    media_type: post.media_type,
    permalink: post.permalink,
    caption: (post.caption || '').substring(0, 500),
    like_count: get('likes'),
    comments_count: get('comments'),
    shares: get('shares'),
    saved: get('saved'),
    reach: get('reach'),
    impressions: get('impressions'),
    views: get('views'),
    thumbnail_url: thumbnailUrl,
    media_url: mediaUrl,
    cover_candidate: coverCandidate
  }
};

